<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../../includes/planeaciones_service.php';
$revisar=($_GET['modulo']??'')==='revisar_planeaciones';validarPermiso($revisar?'revisar_planeaciones':'ver_planeaciones');
try{$f=cufaFiltros();$f['docente_id']=cufaId($_GET,['docente_id']);$f['asignacion_id']=cufaId($_GET,['asignacion_id']);$f['estado']=is_string($_GET['estado']??null)?$_GET['estado']:'';$planes=cufaPlanes($pdo,$f);}catch(Throwable $e){cufaError($e);return;}
?>
<h1 class="text-3xl font-bold mb-6"><?= $revisar?'Revisar':'Ver' ?> planeaciones</h1><p class="mb-6">Consulta de captura por tema, planeación docente, planeación semanal y archivos históricos. Cada registro conserva su origen e identidad.</p>
<?php cufaFiltrosHtml($pdo,$f,$revisar?'revisar_planeaciones':'ver_planeaciones'); ?>
<form method="GET" class="bg-white p-6 rounded-3xl mb-6 flex flex-wrap gap-4"><input type="hidden" name="modulo" value="<?= $revisar?'revisar_planeaciones':'ver_planeaciones' ?>"><?php foreach(['q','carrera_id','periodo_id','grupo_id'] as $k): ?><input type="hidden" name="<?= $k ?>" value="<?= cufaEsc($f[$k]) ?>"><?php endforeach; ?><label>Docente<select name="docente_id" class="border p-3 rounded-xl"><option value="">Todos</option><?php foreach($pdo->query("SELECT d.id,CONCAT_WS(' ',u.nombres,u.apellido_paterno,u.apellido_materno) nombre FROM docentes d JOIN usuarios u ON u.id=d.usuario_id ORDER BY nombre")->fetchAll() as $d): ?><option value="<?= (int)$d['id'] ?>" <?= $f['docente_id']==$d['id']?'selected':'' ?>><?= cufaEsc($d['nombre']) ?></option><?php endforeach; ?></select></label><label>Estado<select name="estado" class="border p-3 rounded-xl"><option value="">Todos</option><?php foreach(['pendiente','revision','aprobado','rechazado','devuelto'] as $st): ?><option value="<?= $st ?>" <?= $f['estado']===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select></label><button class="bg-purple-600 text-white p-3 rounded-xl">Aplicar</button></form>
<div class="overflow-x-auto bg-white rounded-3xl shadow"><table class="w-full"><tr class="bg-purple-200"><th class="p-4">Docente / asignatura</th><th>Grupo / periodo</th><th>Semana / tema</th><th>Estado / origen</th><th>Detalle</th></tr><?php foreach($planes as $p): ?><tr class="border-t"><td class="p-4"><?= cufaEsc($p['docente']) ?><br><?= cufaEsc($p['materia']) ?></td><td><?= cufaEsc($p['grupo'].' / '.$p['periodo']) ?></td><td><?= (int)$p['semana'] ?> · <?= cufaEsc($p['tema']) ?></td><td><?= cufaEsc($p['estado']) ?><br><small><?= cufaEsc($p['origen']) ?> #<?= (int)$p['id'] ?></small></td><td><a href="<?= cufaEsc(cufaPanel('detalle_planeacion',['origen'=>$p['origen'],'id'=>$p['id']])) ?>" class="text-purple-700 underline">Consultar<?= $revisar?' / revisar':'' ?></a></td></tr><?php endforeach; ?></table></div>
<?php if(!$planes): ?><p class="p-6">No hay planeaciones para los filtros seleccionados.</p><?php endif; ?>
